function buildTree(preorder, inorder) {
  const go = (pre, ino) => {
    if (!pre.length) return null;
    const v = pre[0], m = ino.indexOf(v);
    return new TreeNode(v, go(pre.slice(1, m + 1), ino.slice(0, m)), go(pre.slice(m + 1), ino.slice(m + 1)));
  };
  return go(preorder, inorder);
}
